def minSpeed(dist, hour):
    last = dist[-1]
    body = dist[:-1]

    def ok(s):
        total = 0
        for d in body:
            total += (d + s - 1) // s
        return (total * s + last) * 100 <= hour * s

    hi = 10 ** 7
    if not ok(hi):
        return -1
    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
